<?php
declare(strict_types=1);namespace Vendi\Auth;use PDO;use RuntimeException;
final class UserService{public function __construct(private PDO$db){}
 public function roles(int$b):array{$q=$this->db->prepare("SELECT * FROM role_templates WHERE business_id IS NULL OR business_id=? ORDER BY is_system DESC,id");$q->execute([$b]);return$q->fetchAll();}
 public function permissionsForRole(int$b,int$roleId):array{$q=$this->db->prepare("SELECT p.id,p.code,p.name,p.module,COALESCE(rtp.allowed,0) allowed FROM permissions p LEFT JOIN role_template_permissions rtp ON rtp.permission_id=p.id AND rtp.role_template_id=? ORDER BY p.module,p.name");$q->execute([$roleId]);return$q->fetchAll();}
 public function create(int$b,int$branch,array$d):int{$name=trim((string)($d['name']??''));$email=mb_strtolower(trim((string)($d['email']??'')));$pass=(string)($d['password']??'');$roleId=(int)($d['role_template_id']??0);if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8||!$roleId)throw new RuntimeException('Nombre, correo, contraseña de 8 caracteres y rol son obligatorios.');$rq=$this->db->prepare("SELECT code FROM role_templates WHERE id=? AND (business_id IS NULL OR business_id=?)");$rq->execute([$roleId,$b]);$role=$rq->fetchColumn();if(!$role)throw new RuntimeException('Rol inválido.');$legacy=$role==='admin'?'admin':($role==='manager'?'manager':'employee');$this->db->beginTransaction();try{$q=$this->db->prepare("INSERT INTO users(business_id,default_branch_id,name,email,password_hash,role,role_template_id,status) VALUES(?,?,?,?,?,?,?,'active')");$q->execute([$b,$branch,$name,$email,password_hash($pass,PASSWORD_DEFAULT),$legacy,$roleId]);$id=(int)$this->db->lastInsertId();$this->applyRole($id,$roleId,$d['permission_overrides']??[]);$this->db->commit();return$id;}catch(\Throwable$e){$this->db->rollBack();throw$e;}}
 public function applyRole(int$userId,int$roleId,array$overrides=[]):void{$this->db->prepare("DELETE FROM user_permissions WHERE user_id=?")->execute([$userId]);$q=$this->db->prepare("SELECT permission_id,allowed FROM role_template_permissions WHERE role_template_id=?");$q->execute([$roleId]);$map=[];foreach($q->fetchAll()as$r)$map[(int)$r['permission_id']]=(int)$r['allowed'];foreach($overrides as$pid=>$allowed)$map[(int)$pid]=$allowed?1:0;$i=$this->db->prepare("INSERT INTO user_permissions(user_id,permission_id,allowed) VALUES(?,?,?)");foreach($map as$pid=>$allowed)$i->execute([$userId,$pid,$allowed]);}
 public function updatePermissions(int$b,int$userId,array$permissions):void{$q=$this->db->prepare("SELECT id FROM users WHERE id=? AND business_id=?");$q->execute([$userId,$b]);if(!$q->fetchColumn())throw new RuntimeException('Usuario no encontrado.');$this->db->beginTransaction();try{$this->db->prepare("DELETE FROM user_permissions WHERE user_id=?")->execute([$userId]);$i=$this->db->prepare("INSERT INTO user_permissions(user_id,permission_id,allowed) SELECT ?,id,? FROM permissions WHERE id=?");foreach($permissions as$pid=>$allowed)$i->execute([$userId,$allowed?1:0,(int)$pid]);$this->db->commit();}catch(\Throwable$e){$this->db->rollBack();throw$e;}}
}